              "title": "ExploitGym: Can AI Agents Turn Security Vulnerabilities into Real Attacks?",
              "author": "arxiv.org",
              "siteName": "arXiv.org",
              "category": "article",
              "language": null,
              "readingTime": "2 mins",
              "readingMinutes": 2,
              "wordCount": 348,
              "publishedDate": "2026-05-11",
